  ('aff6d7b9-961c-4747-aeea-68134d19d1e8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शैलेंद्र तो फिल्म-निर्माता बनने के लिए सर्वथा अयोग्य थे। राजकपूर ने एक अच्छे और सच्चे मित्र की हैसियत से शैलेंद्र को फिल्म की असफलता के खतरों से आगाह भी किया। पर वह तो एक आदर्शवादी भावुक कवि था, जिसे अपार संपत्ति और यश तक की इतनी कामना नहीं थी जितनी आत्म-संतुष्टि के सुख की अभिलाषा थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('93f23011-98e0-4d71-8b19-4a9808ee8eb7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'तीसरी कसम' कितनी ही महान फिल्म क्यों न रही हो, लेकिन यह एक दुखद सत्य है कि इसे प्रदर्शित करने के लिए बमुश्किल वितरक मिले। बावजूद इसके कि 'तीसरी कसम' में राजकपूर और वहीदा रहमान जैसे नामी सितारे थे, शंकर-जयकिशन का संगीत था, जिनकी लोकप्रियता उन दिनों सातवें आसमान पर थी और इसके गीत भी फिल्म के प्रदर्शन के पूर्व ही बेहद लोकप्रिय हो चुके थे, लेकिन इस फिल्म को खरीदने वाला कोई नहीं था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ac89ea3f-3a0c-4b8d-8c48-bad75f595646', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दरअसल इस फिल्म की संवेदना किसी दो से चार बनाने का गणित जानने वाले की समझ से परे थी। उसमें रची-बसी करुणा तराजू पर तौली जा सकने वाली चीज नहीं थी। इसीलिए बमुश्किल जब 'तीसरी कसम' रिलीज हुई तो इसका कोई प्रचार नहीं हुआ। फिल्म कब आई, कब चली गई, मालूम ही नहीं पड़ा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e95efd41-b92e-4433-9fcc-eed1f689965d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसा नहीं है कि शैलेंद्र बीस सालों तक फिल्म इंडस्ट्री में रहते हुए भी वहां के तौर-तरीकों से नावाकिफ थे, परंतु उनमें उलझकर वे अपनी आदमीयत नहीं खो सके थे। 'श्री 420' का एक लोकप्रिय गीत है—'प्यार हुआ, इकरार हुआ है, प्यार से फिर क्यों डरता है दिल।' इसके अंतरे की एक पंक्ति—'रातें दसों दिशाओं से कहेंगी अपनी कहानियाँ' पर संगीतकार जयकिशन ने आपत्ति की।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9c057acb-3859-428e-b361-51f15e254629', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका ख्याल था कि दर्शक 'चार दिशाएं' तो समझ सकते हैं—'दस दिशाएं' नहीं। लेकिन शैलेंद्र परिवर्तन के लिए तैयार नहीं हुए। उनका दृढ़ मतव्य था कि दर्शकों की रुचि की आड़ में हमें उथलेपन को उन पर नहीं थोपना चाहिए। कलाकार का यह कर्तव्य भी है कि वह उपभोक्ता की रुचियों का परिष्कार करने का प्रयत्न करे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8f9e5bea-7969-469e-bafd-ebf7c2d72299', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और उनका यकीन गलत नहीं था। यही नहीं, वे बहुत अच्छे गीत भी जो उन्होंने लिखे बेहद लोकप्रिय हुए। शैलेंद्र ने झूठे अभिजात्य को कभी नहीं अपनाया। उनके गीत भाव-प्रवण थे—दुरूह नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f029b560-85c3-4460-863e-522e715d4d22', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'मेरा जूता है जापानी, ये पतलून इंगलिस्तानी, सर पे लाल टोपी रूसी, फिर भी दिल है हिंदुस्तानी'—यह गीत शैलेंद्र ही लिख सकते थे। शांत नदी का प्रवाह और समुद्र की गहराई लिए हुए। यही विशेषता उनकी जिंदगी की थी और यही उन्होंने अपनी फिल्म के द्वारा भी साबित किया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9c739c4e-5ba6-46c6-8c73-55583c4b3b8c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'तीसरी कसम' यदि एकमात्र नहीं तो चंद उन फिल्मों में से है जिन्होंने साहित्य-रचना के साथ शत-प्रतिशत न्याय किया हो। शैलेंद्र ने राजकपूर जैसे स्टार को 'हीरामन' बना दिया था। हीरामन पर राजकपूर हावी नहीं हो सका।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('65549977-3049-41bd-9fa5-56fc585a042f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और छींट की सस्ती साड़ी में लिपटी 'हीराबाई' ने वहीदा रहमान की प्रसिद्ध ऊँचाइयों को बहुत पीछे छोड़ दिया था। कजरी नदी के किनारे उकड़ू बैठा हीरामन जब गीत गाते हुए हीराबाई से पूछता है 'मन समझती हैं न आप?' तब हीराबाई जुबान से नहीं, आँखों से बोलती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b9576c18-de12-4be1-a1c7-ea25ff9a4bcd', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शैलेंद्र तो फिल्म-निर्माता बनने के लिए सर्वथा अयोग्य थे। राजकपूर ने एक अच्छे और सच्चे मित्र की हैसियत से शैलेंद्र को फिल्म की असफलता के खतरों से आगाह भी किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('354065c0-a3b1-4bb4-a84a-bdea9afc3eee', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर वह तो एक आदर्शवादी भावुक कवि था, जिसे अपार संपत्ति और यश तक की इतनी कामना नहीं थी जितनी आत्म-संतुष्टि के सुख की अभिलाषा थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('767b663f-5052-4161-b81c-e7d4f66cb5ef', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'तीसरी कसम' कितनी ही महान फिल्म क्यों न रही हो, लेकिन यह एक दुखद सत्य है कि इसे प्रदर्शित करने के लिए बमुश्किल वितरक मिले।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
