  ('57ec9e5a-6993-4d45-afb3-8d730c051df2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसा नहीं है कि शैलेंद्र बीस सालों तक फिल्म इंडस्ट्री में रहते हुए भी वहां के तौर-तरीकों से नावाकिफ थे, परंतु उनमें उलझकर वे अपनी आदमीयत नहीं खो सके थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a35a0049-16d9-45c8-af46-0f73cb2e2ef7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'श्री 420' का एक लोकप्रिय गीत है—'प्यार हुआ, इकरार हुआ है, प्यार से फिर क्यों डरता है दिल।' इसके अंतरे की एक पंक्ति—'रातें दसों दिशाओं से कहेंगी अपनी कहानियाँ' पर संगीतकार जयकिशन ने आपत्ति की।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('17e5cdc7-5e11-48f2-9959-c6e0c4a186c8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका ख्याल था कि दर्शक 'चार दिशाएं' तो समझ सकते हैं—'दस दिशाएं' नहीं। लेकिन शैलेंद्र परिवर्तन के लिए तैयार नहीं हुए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f3bc1b8b-e699-4ba4-b18f-7b2ec450043b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका दृढ़ मतव्य था कि दर्शकों की रुचि की आड़ में हमें उथलेपन को उन पर नहीं थोपना चाहिए। कलाकार का यह कर्तव्य भी है कि वह उपभोक्ता की रुचियों का परिष्कार करने का प्रयत्न करे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('19bf1d1e-a945-4c4d-9d8f-6833729fb413', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और उनका यकीन गलत नहीं था। यही नहीं, वे बहुत अच्छे गीत भी जो उन्होंने लिखे बेहद लोकप्रिय हुए। शैलेंद्र ने झूठे अभिजात्य को कभी नहीं अपनाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f31c20a4-3a62-4189-8848-91b595a30f47', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनके गीत भाव-प्रवण थे—दुरूह नहीं। 'मेरा जूता है जापानी, ये पतलून इंगलिस्तानी, सर पे लाल टोपी रूसी, फिर भी दिल है हिंदुस्तानी'—यह गीत शैलेंद्र ही लिख सकते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6984e205-6c1a-46e7-8cda-33447abdc243', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शांत नदी का प्रवाह और समुद्र की गहराई लिए हुए। यही विशेषता उनकी जिंदगी की थी और यही उन्होंने अपनी फिल्म के द्वारा भी साबित किया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6dff53b2-8773-4817-acdf-795c30f11ef6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'तीसरी कसम' यदि एकमात्र नहीं तो चंद उन फिल्मों में से है जिन्होंने साहित्य-रचना के साथ शत-प्रतिशत न्याय किया हो। शैलेंद्र ने राजकपूर जैसे स्टार को 'हीरामन' बना दिया था। हीरामन पर राजकपूर हावी नहीं हो सका।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b1bf5642-41e3-4c80-9261-72251c58592e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और छींट की सस्ती साड़ी में लिपटी 'हीराबाई' ने वहीदा रहमान की प्रसिद्ध ऊँचाइयों को बहुत पीछे छोड़ दिया था। कजरी नदी के किनारे उकड़ू बैठा हीरामन जब गीत गाते हुए हीराबाई से पूछता है 'मन समझती हैं न आप?' तब हीराबाई जुबान से नहीं, आँखों से बोलती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cdab28f6-7517-4aad-a107-0808dd7605fb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '6b7258e8-7314-45a8-86bb-a0d82e4bd2f6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शैलेंद्र तो फिल्म-निर्माता बनने के लिए सर्वथा अयोग्य थे। राजकपूर ने एक अच्छे और सच्चे मित्र की हैसियत से शैलेंद्र को फिल्म की असफलता के खतरों से आगाह भी किया। पर वह तो एक आदर्शवादी भावुक कवि था, जिसे अपार संपत्ति और यश तक की इतनी कामना नहीं थी जितनी आत्म-संतुष्टि के सुख की अभिलाषा थी। 'तीसरी कसम' कितनी ही महान फिल्म क्यों न रही हो, लेकिन यह एक दुखद सत्य है कि इसे प्रदर्शित करने के लिए बमुश्किल वितरक मिले।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-234Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
